    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testRegression_property() public {
        // Alice is a user who is not the owner
        address alice = address(0x1234);
        // Try to deposit from alice's perspective; the reference requires msg.sender == owner (alice == alice works)
        vm.prank(alice);
        bool ok;
        try c.deposit(100, alice) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference passes (deposit succeeds because caller equals receiver, so withApproval passes)
        // Mutant also passes (no modifier, so always succeeds)
        // To force a divergence, we need a case where the reference reverts and the mutant does not.
        // Let the receiver be a different address than caller.
        address bob = address(0x5678);
        vm.prank(alice);
        try c.deposit(200, bob) {
            ok = true;
        } catch {
            ok = false;
        }
        // In the reference, withApproval(bob) requires msg.sender == bob, but msg.sender is alice -> revert, so ok = false.
        // In the mutant (no modifier), deposit succeeds, so ok = true.
        // Assert that the call did NOT revert (mutant behavior). The reference would assert false, but we want test to fail on mutant.
        // Actually we need the assertion to be true on reference and false on mutant.
        // On reference: ok == false (because revert), on mutant: ok == true.
        // So we assertTrue(!ok) -> reference: true, mutant: false. That is what we want.
        assertTrue(!ok);
    }
}

