import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address alice = address(0x1234);
    address bob = address(0x5678);

    function setUp() public { 
        c = new C(0, bytes16(0), address(this), address(this), address(this)); 
        // set up mock InvestmentManager that accepts any mint
        vm.mockCall(
            address(this),
            abi.encodeWithSelector(c.processMint.selector),
            abi.encode(100)
        );
    }

    function testRegression_property() public {
        // Alice tries to mint shares for Bob, but she is not the receiver
        vm.prank(alice);

        // Try catch to handle revert in reference version
        bool ok;
        try c.mint(1000, bob) {
            ok = true;
        } catch {
            ok = false;
        }

        // In reference: alice != bob, so withApproval(bob) reverts -> ok = false
        // In modified: modifier removed, so call succeeds -> ok = true
        assertFalse(ok);
    }
}

